items.code:
extends Resource

# Это название нашего ресурса
class_name ItemData

@export var name: String = ''
@export var icon: Texture2D
@export var is_tool: bool = false
@export var damage: int = 0

extends CanvasLayer

@export var grid: GridContainer

func _ready():
	Global.inventory_updated.connect(refresh_ui)
	refresh_ui()

func refresh_ui():
	# Очистка старых слотов
	for child in grid.get_children(): child.queue_free()

	# Создание новых на основе данных из Global
	for item in Global.inventory:
		var slot = TextureRect.new()
		slot.texture = item.icon
		grid.add_child(slot)

extends Node2D

@export var item_resources: ItemData

# Если в Area2D находиться любое body, вызывается данная функция
func _on_area_2d_body_entered(body: Node2D) -> void:
	# Проверка body = Player
	if body.name == 'Player':
		# Вызов add_item с ресурсом ItemData
		Global.add_item(item_resources)
		# Удаление предмета
		queue_free()

@export var hand: Sprite2D

func _unhandled_input(event):
	if event.is_action_pressed('use_tool'):
		if Global.inventory.size() > 0:
			var item = Global.inventory[0]
			if item.is_tool:
				hand.texture = item.icon

func _on_area_entered(area):
	# Предположим, у игрока есть зона поражения инструмента
	var current_tool = PlayerData.equipped_tool 
	if current_tool and current_tool.name == 'Axe':
		spawn_wood()
		queue_free()
